// Calculate expiry status for each gym member
const today = new Date();
today.setHours(0,0,0,0);

const results = [];
let activeCount = 0;
let expiringCount = 0;
let expiredCount = 0;

for (const item of $input.all()) {
  const member = item.json;
  const expiry = new Date(member.expiryDate);
  expiry.setHours(0,0,0,0);

  const diffDays = Math.round((expiry - today) / (1000 * 60 * 60 * 24));

  let status = 'active';
  let needsReminder = false;
  let reminderType = '';

  if (diffDays < 0) {
    status = 'expired';
    expiredCount++;
    needsReminder = true;
    reminderType = 'expired';
  } else if (diffDays === 0) {
    status = 'expiring_today';
    expiringCount++;
    needsReminder = true;
    reminderType = 'today';
  } else if (diffDays <= 3) {
    status = 'expiring_soon';
    expiringCount++;
    needsReminder = true;
    reminderType = 'soon';
  } else {
    activeCount++;
  }

  results.push({
    json: {
      ...member,
      diffDays,
      status,
      needsReminder,
      reminderType,
      formattedExpiry: expiry.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
    }
  });
}

return results;

